export const PENDING_MIGRATIONS: EmbeddedMigration[] = [
  { name: "migration_makes_brands.sql", sql: "-- Makes and Brands for the CRM product catalogue (Spark & Ray).\n-- A \"make\" is the manufacturer; a \"brand\" is the product brand sold (MAC, PHD, BEKO, PIAB ...).\n-- They are separate lists, and every product links to at most one make and one brand.\n-- Additive + idempotent. NOT applied automatically: the operator runs it, then NOTIFY pgrst, 'reload schema'\n-- (deliberately not part of this file).\n-- Conventions mirrored from migration_crm_sites_visits_attendance_sessions.sql: gen_random_uuid() ids, RLS with the\n-- tenant_isolation policy (org_id = auth.jwt()->>'org_id'), grants to authenticated/service_role, set_updated_at()\n-- trigger. The service-role backend (supabaseAdmin) bypasses RLS.\n--\n-- Until this is applied the API answers 503 NOT_MIGRATED on /makes, /brands and on product make/brand writes;\n-- product reads keep working (make_name / brand_name come back null).\n\nBEGIN;\n\n-- ============================================================= crm_makes / crm_brands\nCREATE TABLE IF NOT EXISTS public.crm_makes (\n  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  org_id      uuid NOT NULL,\n  client_id   uuid,\n  name        text NOT NULL,\n  description text,\n  is_active   boolean NOT NULL DEFAULT true,\n  sort_order  integer DEFAULT 0,\n  created_at  timestamptz NOT NULL DEFAULT now(),\n  updated_at  timestamptz NOT NULL DEFAULT now(),\n  created_by  uuid,\n  deleted_at  timestamptz\n);\n\nCREATE TABLE IF NOT EXISTS public.crm_brands (\n  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  org_id      uuid NOT NULL,\n  client_id   uuid,\n  name        text NOT NULL,\n  description text,\n  is_active   boolean NOT NULL DEFAULT true,\n  sort_order  integer DEFAULT 0,\n  created_at  timestamptz NOT NULL DEFAULT now(),\n  updated_at  timestamptz NOT NULL DEFAULT now(),\n  created_by  uuid,\n  deleted_at  timestamptz\n);\n\nCREATE INDEX IF NOT EXISTS idx_crm_makes_org  ON public.crm_makes  (org_id);\nCREATE INDEX IF NOT EXISTS idx_crm_brands_org ON public.crm_brands (org_id);\n\n-- A name is unique per org + client (client NULL = the org-level list), case-insensitive, among live rows.\nCREATE UNIQUE INDEX IF NOT EXISTS uq_crm_makes_org_client_name\n  ON public.crm_makes (org_id, (COALESCE(client_id, '00000000-0000-0000-0000-000000000000'::uuid)), lower(name))\n  WHERE deleted_at IS NULL;\nCREATE UNIQUE INDEX IF NOT EXISTS uq_crm_brands_org_client_name\n  ON public.crm_brands (org_id, (COALESCE(client_id, '00000000-0000-0000-0000-000000000000'::uuid)), lower(name))\n  WHERE deleted_at IS NULL;\n\n-- ============================================================= RLS, grants, triggers\nDO $$\nDECLARE t text;\nBEGIN\n  FOREACH t IN ARRAY ARRAY['crm_makes','crm_brands'] LOOP\n    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);\n    IF NOT EXISTS (SELECT 1 FROM pg_policy WHERE polname = 'tenant_isolation'\n                   AND polrelid = format('public.%I', t)::regclass) THEN\n      EXECUTE format($f$CREATE POLICY tenant_isolation ON public.%I\n        USING (org_id = ((( SELECT auth.jwt() AS jwt) ->> 'org_id'::text))::uuid)\n        WITH CHECK (org_id = ((( SELECT auth.jwt() AS jwt) ->> 'org_id'::text))::uuid)$f$, t);\n    END IF;\n    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated, service_role', t);\n    IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'trg_'||t||'_updated'\n                   AND tgrelid = format('public.%I', t)::regclass) THEN\n      EXECUTE format('CREATE TRIGGER trg_%s_updated BEFORE UPDATE ON public.%I\n        FOR EACH ROW EXECUTE FUNCTION set_updated_at()', t, t);\n    END IF;\n  END LOOP;\nEND $$;\n\n-- ============================================================= products link to one make and one brand\nALTER TABLE public.crm_products ADD COLUMN IF NOT EXISTS make_id  uuid REFERENCES public.crm_makes(id);\nALTER TABLE public.crm_products ADD COLUMN IF NOT EXISTS brand_id uuid REFERENCES public.crm_brands(id);\n\nCREATE INDEX IF NOT EXISTS idx_crm_products_make  ON public.crm_products (make_id);\nCREATE INDEX IF NOT EXISTS idx_crm_products_brand ON public.crm_products (brand_id);\n\n-- Speeds up the product-reference uniqueness check and the bulk import (the API compares case-insensitively).\n-- Not UNIQUE: existing data may already hold duplicate references; the API enforces uniqueness for new writes.\n-- Guarded so a database whose crm_products has no `sku` column still migrates cleanly.\nDO $$\nBEGIN\n  IF EXISTS (SELECT 1 FROM information_schema.columns\n             WHERE table_schema = 'public' AND table_name = 'crm_products' AND column_name = 'sku') THEN\n    CREATE INDEX IF NOT EXISTS idx_crm_products_org_sku_lower\n      ON public.crm_products (org_id, lower(sku)) WHERE deleted_at IS NULL;\n  END IF;\nEND $$;\n\nCOMMIT;\n" },
  { name: "migration_lead_ref_and_type.sql", sql: "-- Lead numbers (e.g. SR/LD/2627-12) + lead type (requirement | discussion) on crm_leads.\n-- Additive and idempotent. NOT applied automatically: the operator runs it on the Kinematic tenant DB, then sends\n--   NOTIFY pgrst, 'reload schema';\n-- (deliberately not part of this file).\n--\n-- Numbering is opt-in in code: only connected-B2B clients (Spark & Ray) get a ref_no, prefix from\n-- clients.settings.lead_ref_prefix (default SR/LD). Until this runs, lead create/edit keep working (the API retries\n-- without the two new columns) and POST /api/v1/crm/leads/ref-numbers/backfill answers 503 NOT_MIGRATED.\nbegin;\n\n-- 1. The lead number and the lead type.\nalter table crm_leads add column if not exists ref_no    text;\nalter table crm_leads add column if not exists lead_type text;\n\n-- lead_type is one of two values (or empty). Added idempotently: ADD CONSTRAINT has no IF NOT EXISTS.\ndo $$ begin\n  if not exists (\n    select 1 from pg_constraint\n    where conname = 'crm_leads_lead_type_check' and conrelid = 'crm_leads'::regclass\n  ) then\n    alter table crm_leads\n      add constraint crm_leads_lead_type_check\n      check (lead_type is null or lead_type in ('requirement', 'discussion'));\n  end if;\nend $$;\n\n-- 2. A lead number is unique per org + client (leads without a client share the all-zero key).\ncreate unique index if not exists crm_leads_org_client_ref_no_uidx\n  on crm_leads (org_id, coalesce(client_id, '00000000-0000-0000-0000-000000000000'::uuid), ref_no)\n  where ref_no is not null;\n\n-- Fast lookup by number (search, exact filter, email-subject trace).\ncreate index if not exists crm_leads_ref_no_idx\n  on crm_leads (ref_no) where ref_no is not null;\n\n-- 3. One running counter per client per series (prefix + financial year, e.g. 'SR/LD/2627').\ncreate table if not exists lead_ref_counters (\n  client_id  uuid        not null,\n  series     text        not null,\n  last_value bigint      not null default 0,\n  updated_at timestamptz not null default now(),\n  primary key (client_id, series)\n);\nalter table lead_ref_counters enable row level security;   -- no policies: service role only\n\n-- Atomic: concurrent creates can never be handed the same number.\ncreate or replace function next_lead_ref(p_client uuid, p_series text) returns bigint\nlanguage sql as $$\n  insert into lead_ref_counters (client_id, series, last_value) values (p_client, p_series, 1)\n  on conflict (client_id, series) do update\n    set last_value = lead_ref_counters.last_value + 1, updated_at = now()\n  returning last_value;\n$$;\nrevoke all on function next_lead_ref(uuid, text) from public;\ndo $$ begin\n  if exists (select 1 from pg_roles where rolname = 'service_role') then\n    grant execute on function next_lead_ref(uuid, text) to service_role;\n  end if;\nend $$;\n\ncommit;\n" },
  { name: "migration_expense_lead_deal_links.sql", sql: "-- Expense ↔ lead / deal links (connected-B2B flow). Additive + idempotent.\n--\n--   * expense_claims.lead_id — the CRM lead this expense was spent on.\n--   * expense_claims.deal_id — the CRM deal this expense was spent on (a deal's\n--                              claims also carry its lead_id; the backend derives it).\n--\n-- They feed the per-lead / per-deal cost roll-up (total spend, visits and spend\n-- as a % of the opportunity value) served by GET /api/v1/crm/leads/:id/expenses\n-- and /deals/:id/expenses.\n--\n-- No new tables, so the existing RLS / tenant grants on expense_claims already\n-- cover these columns. The backend writes them ONLY for connected-B2B clients\n-- and reads via select('*'), and a write that fails because the columns are\n-- missing is retried without them, so a tenant that has not run this migration\n-- is unaffected (the roll-up then answers zeros). Apply to the Kinematic tenant\n-- database (Spark & Ray lives under it).\n\nBEGIN;\n\nALTER TABLE public.expense_claims ADD COLUMN IF NOT EXISTS lead_id uuid REFERENCES public.crm_leads(id);\nALTER TABLE public.expense_claims ADD COLUMN IF NOT EXISTS deal_id uuid REFERENCES public.crm_deals(id);\n\nCREATE INDEX IF NOT EXISTS idx_expense_claims_lead ON public.expense_claims (lead_id);\nCREATE INDEX IF NOT EXISTS idx_expense_claims_deal ON public.expense_claims (deal_id);\n\nCOMMIT;\n" },
  { name: "migration_expense_links_clarification.sql", sql: "-- Expense ↔ account/form links + a claim-level clarification (Spark & Ray\n-- connected-B2B flow). Additive + idempotent.\n--\n--   * expense_claims.clarification — the mandatory purpose/justification a rep\n--                                    gives for the claim (enforced at submit for\n--                                    B2B clients only; optional column otherwise).\n--   * expense_claims.account_id    — the CRM account this expense is against.\n--   * expense_claims.form_id       — the builder form this expense is linked to\n--                                    (its title is shown wherever the link appears).\n--   * builder_forms.expense_linked — admin toggle in the Form Builder marking a\n--                                    form as linkable to expenses (the expense\n--                                    form-picker lists these).\n--\n-- No new tables, so the existing RLS / tenant grants on expense_claims and\n-- builder_forms already cover these columns. Kinematic tenant only (Spark lives\n-- under it); the backend writes the new expense columns ONLY for B2B clients and\n-- reads via select('*'), so a tenant without this migration is unaffected.\n\nBEGIN;\n\nALTER TABLE public.expense_claims ADD COLUMN IF NOT EXISTS clarification text;\nALTER TABLE public.expense_claims ADD COLUMN IF NOT EXISTS account_id uuid REFERENCES public.crm_accounts(id);\nALTER TABLE public.expense_claims ADD COLUMN IF NOT EXISTS form_id    uuid REFERENCES public.builder_forms(id);\n\nCREATE INDEX IF NOT EXISTS idx_expense_claims_account ON public.expense_claims (account_id);\nCREATE INDEX IF NOT EXISTS idx_expense_claims_form    ON public.expense_claims (form_id);\n\nALTER TABLE public.builder_forms ADD COLUMN IF NOT EXISTS expense_linked boolean NOT NULL DEFAULT false;\n\nCOMMIT;\n" },
  { name: "migration_form_ref_no.sql", sql: "-- Form reference numbers (e.g. SRPR2627-1) + expense claim -> filled form link.\n-- Additive and idempotent. Apply to the Kinematic tenant DB, then\n--   NOTIFY pgrst, 'reload schema';\n-- Numbering is opt-in: connected-B2B clients (Spark & Ray) that also carry\n-- clients.settings.form_ref_prefix, so nothing changes for any other client.\nbegin;\n\n-- 1. The reference on each filled form; unique per client.\nalter table form_submissions add column if not exists ref_no text;\ncreate unique index if not exists form_submissions_client_ref_no_uidx\n  on form_submissions (client_id, ref_no) where ref_no is not null;\n\n-- 2. One running counter per client per series (prefix + financial year).\ncreate table if not exists form_ref_counters (\n  client_id  uuid        not null,\n  series     text        not null,\n  last_value integer     not null default 0,\n  updated_at timestamptz not null default now(),\n  primary key (client_id, series)\n);\nalter table form_ref_counters enable row level security;   -- no policies: service role only\n\n-- Atomic: concurrent submissions can never be handed the same number.\ncreate or replace function next_form_ref(p_client uuid, p_series text) returns integer\nlanguage sql as $$\n  insert into form_ref_counters (client_id, series, last_value) values (p_client, p_series, 1)\n  on conflict (client_id, series) do update\n    set last_value = form_ref_counters.last_value + 1, updated_at = now()\n  returning last_value;\n$$;\nrevoke all on function next_form_ref(uuid, text) from public;\ndo $$ begin\n  if exists (select 1 from pg_roles where rolname = 'service_role') then\n    grant execute on function next_form_ref(uuid, text) to service_role;\n  end if;\nend $$;\n\n-- 3. An expense claim can link to a filled form (shown as its reference + date).\nalter table expense_claims add column if not exists form_submission_id uuid\n  references form_submissions(id) on delete set null;\ncreate index if not exists expense_claims_form_submission_idx\n  on expense_claims (form_submission_id) where form_submission_id is not null;\n\ncommit;\nnotify pgrst, 'reload schema';\n" },
  { name: "migration_account_location.sql", sql: "-- Account location columns. The Kinematic tenant's crm_accounts was created without them, so a save that included\n-- an address failed with \"Could not find the 'address_line1' column of 'crm_accounts' in the schema cache\".\n-- Additive and idempotent. Run, then: NOTIFY pgrst, 'reload schema';\nALTER TABLE public.crm_accounts ADD COLUMN IF NOT EXISTS address_line1 text;\nALTER TABLE public.crm_accounts ADD COLUMN IF NOT EXISTS address_line2 text;\nALTER TABLE public.crm_accounts ADD COLUMN IF NOT EXISTS city          text;\nALTER TABLE public.crm_accounts ADD COLUMN IF NOT EXISTS state         text;\nALTER TABLE public.crm_accounts ADD COLUMN IF NOT EXISTS postal_code   text;\nALTER TABLE public.crm_accounts ADD COLUMN IF NOT EXISTS country       text DEFAULT 'India';\nALTER TABLE public.crm_accounts ADD COLUMN IF NOT EXISTS email         text;\n\n-- Accounts created while a column was missing kept what the rep typed in custom_fields.location; copy it across.\nUPDATE public.crm_accounts a SET\n  address_line1 = COALESCE(a.address_line1, a.custom_fields #>> '{location,address_line1}'),\n  address_line2 = COALESCE(a.address_line2, a.custom_fields #>> '{location,address_line2}'),\n  city          = COALESCE(a.city,          a.custom_fields #>> '{location,city}'),\n  state         = COALESCE(a.state,         a.custom_fields #>> '{location,state}'),\n  postal_code   = COALESCE(a.postal_code,   a.custom_fields #>> '{location,postal_code}'),\n  country       = COALESCE(a.country,       a.custom_fields #>> '{location,country}'),\n  email         = COALESCE(a.email,         a.custom_fields #>> '{location,email}')\nWHERE a.custom_fields ? 'location';\n\nNOTIFY pgrst, 'reload schema';\n" },
  { name: "migration_activity_type_check.sql", sql: "-- Custom activity types. crm_activities.type was created with CHECK (type IN ('call','email','meeting','task','note',\n-- 'sms','whatsapp')), so an activity of an admin-defined type (Settings -> Activity types) failed with\n--   new row for relation \"crm_activities\" violates check constraint \"crm_activities_type_check\".\n-- Replace it with a format check (the same shape the API accepts), then move rows the API saved under a carrier type\n-- (type 'note' + metadata.activity_type, see src/services/crm/activityTypeFallback.ts) back to their real type.\n-- Additive in effect, idempotent. After it runs: NOTIFY pgrst, 'reload schema';\nALTER TABLE public.crm_activities DROP CONSTRAINT IF EXISTS crm_activities_type_check;\nALTER TABLE public.crm_activities\n  ADD CONSTRAINT crm_activities_type_check CHECK (type ~ '^[A-Za-z0-9][A-Za-z0-9_-]{0,39}$');\n\nUPDATE public.crm_activities\n   SET type = metadata::jsonb ->> 'activity_type'\n WHERE type = 'note'\n   AND metadata IS NOT NULL\n   AND (metadata::jsonb ->> 'activity_type') ~ '^[A-Za-z0-9][A-Za-z0-9_-]{0,39}$';\n\nNOTIFY pgrst, 'reload schema';\n" },
  { name: "migration_user_roles.sql", sql: "-- Multiple roles per user (additive).\n--\n-- Today each user holds exactly ONE hierarchy role via users.org_role_id. This\n-- adds a join table so a user can be assigned SEVERAL org_roles at once, with\n-- their effective module permissions resolved as the UNION of every role.\n--\n-- Back-compat: users.org_role_id is UNCHANGED and remains the user's PRIMARY\n-- role (it still drives the displayed designation + data_scope). Rows in\n-- user_roles are purely ADDITIONAL roles layered on top. A user with no rows\n-- here behaves exactly as before.\n--\n-- Additive + idempotent (CREATE TABLE IF NOT EXISTS). NOT applied automatically\n-- by hand: the operator runs it (or the boot-time auto-migrate runner does),\n-- then NOTIFY pgrst, 'reload schema' (deliberately not part of this file).\n-- Conventions mirrored from migration_makes_brands.sql: RLS with the\n-- tenant_isolation policy (org_id = auth.jwt()->>'org_id'), grants to\n-- authenticated/service_role. The service-role backend (supabaseAdmin) bypasses\n-- RLS. There is no updated_at column (a pure join row is never edited in place),\n-- so no set_updated_at() trigger is attached.\n--\n-- NOTE: no top-level BEGIN;/COMMIT; wrapper. The boot-time runner applies this\n-- through the exec_migration() RPC (PL/pgSQL EXECUTE), which cannot run\n-- transaction-control statements (\"EXECUTE of transaction commands is not\n-- implemented\") — the function call is already atomic. (The other migrations\n-- that still carry BEGIN;/COMMIT; were applied via direct psql, never through\n-- this RPC, so they never hit that limitation.) psql -1 would also run this\n-- file atomically, so dropping the wrapper is safe on both paths.\n\n-- ============================================================= user_roles join table\n-- One row per (user, additional role). The user's PRIMARY role stays on\n-- users.org_role_id and is NOT duplicated here. ON DELETE CASCADE keeps the\n-- join clean when either the user or the role is removed.\nCREATE TABLE IF NOT EXISTS public.user_roles (\n  user_id     uuid NOT NULL REFERENCES public.users(id)     ON DELETE CASCADE,\n  org_role_id uuid NOT NULL REFERENCES public.org_roles(id) ON DELETE CASCADE,\n  org_id      uuid NOT NULL,\n  client_id   uuid,\n  created_at  timestamptz NOT NULL DEFAULT now(),\n  created_by  uuid,\n  PRIMARY KEY (user_id, org_role_id)\n);\n\nCREATE INDEX IF NOT EXISTS idx_user_roles_user ON public.user_roles (user_id);\nCREATE INDEX IF NOT EXISTS idx_user_roles_role ON public.user_roles (org_role_id);\nCREATE INDEX IF NOT EXISTS idx_user_roles_org  ON public.user_roles (org_id);\n\n-- ============================================================= RLS + grants\nDO $$\nBEGIN\n  EXECUTE 'ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY';\n  IF NOT EXISTS (SELECT 1 FROM pg_policy WHERE polname = 'tenant_isolation'\n                 AND polrelid = 'public.user_roles'::regclass) THEN\n    EXECUTE $f$CREATE POLICY tenant_isolation ON public.user_roles\n      USING (org_id = ((( SELECT auth.jwt() AS jwt) ->> 'org_id'::text))::uuid)\n      WITH CHECK (org_id = ((( SELECT auth.jwt() AS jwt) ->> 'org_id'::text))::uuid)$f$;\n  END IF;\n  EXECUTE 'GRANT SELECT, INSERT, UPDATE, DELETE ON public.user_roles TO authenticated, service_role';\nEND $$;\n" },
  { name: "migration_account_geo.sql", sql: "-- Account geofence columns. The web + mobile New Account forms send latitude/longitude from the Google place\n-- pick, but crm_accounts had no columns to hold them, so the geofence was lost on save.\n-- Additive and idempotent. Run, then: NOTIFY pgrst, 'reload schema';\nALTER TABLE public.crm_accounts ADD COLUMN IF NOT EXISTS latitude  double precision;\nALTER TABLE public.crm_accounts ADD COLUMN IF NOT EXISTS longitude double precision;\n\nNOTIFY pgrst, 'reload schema';\n" },
  { name: "migration_spark_lead_structure.sql", sql: "-- Spark & Ray refined lead structure. Additive + idempotent. Applied at boot via\n-- exec_migration (PL/pgSQL EXECUTE) — so NO top-level BEGIN/COMMIT (those can't run there).\n-- Every feature here is gated to connected-B2B clients (Spark & Ray) in the API, so a\n-- tenant whose database has run this file but is not a B2B client is never touched.\n-- After apply the runner issues: NOTIFY pgrst, 'reload schema';\n--\n-- Adds, end to end, the chain the field team actually sells on:\n--   Group → Company → Location → Plant/Unit → Department → Person → Requirement → Make·Product·Qty\n--\n--   1. crm_accounts.is_group            — marks an account that only groups its children\n--                                         (the \"group\" is a parent account; parent_account_id\n--                                         already exists, so NINL → Tata Steel is parent_account_id).\n--   2. crm_sites.parent_site_id         — a Location (site) holds one or more Plants/Units (child sites).\n--      crm_sites.site_kind              — 'location' | 'unit' (NULL = legacy flat site).\n--   3. crm_leads.site_id                — the plant/unit this requirement is for.\n--      crm_leads.requirement            — the requirement text (one lead = one requirement).\n--      crm_leads.department             — the contact's department, denormalised for naming/filtering.\n--      crm_leads.display_name           — the computed, human-readable lead name.\n--   4. crm_lead_product_lines           — several make/product/qty rows under one requirement.\n\n-- ============================================================= 1. account group\nALTER TABLE public.crm_accounts ADD COLUMN IF NOT EXISTS is_group boolean NOT NULL DEFAULT false;\nCREATE INDEX IF NOT EXISTS idx_crm_accounts_parent ON public.crm_accounts (parent_account_id);\n\n-- ============================================================= 2. nested sites (location → unit)\nALTER TABLE public.crm_sites ADD COLUMN IF NOT EXISTS parent_site_id uuid REFERENCES public.crm_sites(id);\nALTER TABLE public.crm_sites ADD COLUMN IF NOT EXISTS site_kind      text;   -- 'location' | 'unit'\nCREATE INDEX IF NOT EXISTS idx_crm_sites_parent ON public.crm_sites (parent_site_id);\n\n-- ============================================================= 3. lead plant / requirement / name\nALTER TABLE public.crm_leads ADD COLUMN IF NOT EXISTS site_id      uuid REFERENCES public.crm_sites(id);\nALTER TABLE public.crm_leads ADD COLUMN IF NOT EXISTS requirement  text;\nALTER TABLE public.crm_leads ADD COLUMN IF NOT EXISTS department   text;\nALTER TABLE public.crm_leads ADD COLUMN IF NOT EXISTS display_name text;\nCREATE INDEX IF NOT EXISTS idx_crm_leads_site ON public.crm_leads (site_id);\n\n-- ============================================================= 4. product lines per requirement\nCREATE TABLE IF NOT EXISTS public.crm_lead_product_lines (\n  id            uuid        PRIMARY KEY DEFAULT gen_random_uuid(),\n  org_id        uuid        NOT NULL,\n  client_id     uuid,\n  lead_id       uuid        NOT NULL REFERENCES public.crm_leads(id) ON DELETE CASCADE,\n  make_id       uuid        REFERENCES public.crm_makes(id),\n  make_name     text,\n  product_id    uuid        REFERENCES public.crm_products(id),\n  product_name  text,\n  qty           numeric,\n  unit          text,\n  line_value    numeric,\n  position      integer     NOT NULL DEFAULT 0,\n  custom_fields jsonb       NOT NULL DEFAULT '{}'::jsonb,\n  created_at    timestamptz NOT NULL DEFAULT now(),\n  updated_at    timestamptz NOT NULL DEFAULT now(),\n  created_by    uuid,\n  updated_by    uuid,\n  deleted_at    timestamptz\n);\nCREATE INDEX IF NOT EXISTS idx_crm_lpl_lead    ON public.crm_lead_product_lines (lead_id);\nCREATE INDEX IF NOT EXISTS idx_crm_lpl_org     ON public.crm_lead_product_lines (org_id);\nCREATE INDEX IF NOT EXISTS idx_crm_lpl_make    ON public.crm_lead_product_lines (make_id)    WHERE make_id    IS NOT NULL;\nCREATE INDEX IF NOT EXISTS idx_crm_lpl_product ON public.crm_lead_product_lines (product_id) WHERE product_id IS NOT NULL;\n\n-- RLS: service-role backend (supabaseAdmin) bypasses RLS; enable it so no other role can read,\n-- matching the sibling Spark tables (crm_account_updates, crm_activity_assignees). Idempotent.\nDO $$\nBEGIN\n  EXECUTE 'ALTER TABLE public.crm_lead_product_lines ENABLE ROW LEVEL SECURITY';\n  EXECUTE 'GRANT SELECT, INSERT, UPDATE, DELETE ON public.crm_lead_product_lines TO authenticated, service_role';\nEND $$;\n\nNOTIFY pgrst, 'reload schema';\n" },
  { name: "migration_lead_contacts.sql", sql: "-- Spark & Ray: several customer contacts on one lead, with one marked primary (nodal).\n-- Additive + idempotent. Applied at boot via exec_migration (PL/pgSQL EXECUTE) — so NO\n-- top-level BEGIN/COMMIT. Gated to connected-B2B clients (Spark & Ray) in the API, so a\n-- tenant whose database has run this file but is not a B2B client is never written.\n-- After apply the runner issues: NOTIFY pgrst, 'reload schema';\n--\n-- Why a join table: a lead involves several people on the customer's team (GM / DGM / AGM /\n-- procurement / senior manager). crm_contacts.lead_id holds only ONE lead per contact, so it\n-- cannot express \"several contacts on one lead, one of them primary\". Each row here links a\n-- lead to a contact; exactly one is is_primary (the nodal point, which changes over the deal),\n-- with an optional free-text role. The requirement/plant stay on the lead; only the people vary.\n\nCREATE TABLE IF NOT EXISTS public.crm_lead_contacts (\n  id          uuid        PRIMARY KEY DEFAULT gen_random_uuid(),\n  org_id      uuid        NOT NULL,\n  client_id   uuid,\n  lead_id     uuid        NOT NULL REFERENCES public.crm_leads(id)    ON DELETE CASCADE,\n  contact_id  uuid        NOT NULL REFERENCES public.crm_contacts(id) ON DELETE CASCADE,\n  is_primary  boolean     NOT NULL DEFAULT false,\n  role        text,                 -- free text: 'Procurement', 'DGM', 'Senior Manager', ...\n  position    integer     NOT NULL DEFAULT 0,\n  created_at  timestamptz NOT NULL DEFAULT now(),\n  updated_at  timestamptz NOT NULL DEFAULT now(),\n  created_by  uuid,\n  updated_by  uuid,\n  deleted_at  timestamptz\n);\n\n-- One live link per (lead, contact): re-adding the same person updates the row, never duplicates.\nCREATE UNIQUE INDEX IF NOT EXISTS ux_crm_lead_contacts_lead_contact\n  ON public.crm_lead_contacts (lead_id, contact_id) WHERE deleted_at IS NULL;\n-- At most one primary (nodal) contact per lead.\nCREATE UNIQUE INDEX IF NOT EXISTS ux_crm_lead_contacts_one_primary\n  ON public.crm_lead_contacts (lead_id) WHERE is_primary AND deleted_at IS NULL;\nCREATE INDEX IF NOT EXISTS idx_crm_lead_contacts_lead    ON public.crm_lead_contacts (lead_id);\nCREATE INDEX IF NOT EXISTS idx_crm_lead_contacts_contact ON public.crm_lead_contacts (contact_id);\nCREATE INDEX IF NOT EXISTS idx_crm_lead_contacts_org     ON public.crm_lead_contacts (org_id);\n\n-- RLS: the service-role backend (supabaseAdmin) bypasses RLS; enable it so no other role can\n-- read, matching the sibling Spark tables (crm_lead_product_lines, crm_activity_assignees).\nDO $$\nBEGIN\n  EXECUTE 'ALTER TABLE public.crm_lead_contacts ENABLE ROW LEVEL SECURITY';\n  EXECUTE 'GRANT SELECT, INSERT, UPDATE, DELETE ON public.crm_lead_contacts TO authenticated, service_role';\nEND $$;\n\nNOTIFY pgrst, 'reload schema';\n" },
  { name: "migration_client_daily_summary_log.sql", sql: "-- Dedup ledger for the 7 pm WhatsApp manager summary (services/clientDailySummary.service.ts).\n-- The sender claims (org_id, summary_date) before sending, so each client gets at most one summary per IST day even\n-- across overlapping ticks or several backend instances. Additive and idempotent. Kinematic project only.\nCREATE TABLE IF NOT EXISTS public.client_daily_summary_log (\n  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  org_id       uuid NOT NULL,\n  summary_date date NOT NULL,\n  created_at   timestamptz NOT NULL DEFAULT now()\n);\nCREATE UNIQUE INDEX IF NOT EXISTS uq_client_daily_summary\n  ON public.client_daily_summary_log (org_id, summary_date);\nALTER TABLE public.client_daily_summary_log ENABLE ROW LEVEL SECURITY;  -- deny-by-default; service-role bypasses\nNOTIFY pgrst, 'reload schema';\n" },
  { name: "migration_deal_trial_dispatch.sql", sql: "-- Spark & Ray product-trial dispatch details on crm_deals: the sample sent for a trial is couriered,\n-- so the Product trial deal section needs its logistics — the airway bill / docket number, free-text\n-- shipment details (carrier, what was sent, how) and the value of the sample shipped (INR).\n-- Additive + idempotent. Applied at boot via exec_migration (PL/pgSQL EXECUTE) — so NO top-level\n-- BEGIN/COMMIT. Gated to connected-B2B clients (Spark & Ray) in the API (DEAL_SECTION_KEYS), so a\n-- tenant whose database has run this file but is not a B2B client is never written these columns.\n-- After apply the runner issues: NOTIFY pgrst, 'reload schema';\nALTER TABLE public.crm_deals ADD COLUMN IF NOT EXISTS trial_awb      text;\nALTER TABLE public.crm_deals ADD COLUMN IF NOT EXISTS trial_shipment text;\nALTER TABLE public.crm_deals ADD COLUMN IF NOT EXISTS trial_value    numeric;\n\nNOTIFY pgrst, 'reload schema';\n" },
  { name: "migration_record_owners.sql", sql: "-- Co-owners (additional owners) on a CRM lead / account / contact / deal.\n-- Additive + idempotent. Applied at boot via exec_migration (PL/pgSQL EXECUTE) — so NO top-level\n-- BEGIN/COMMIT. After apply the runner issues: NOTIFY pgrst, 'reload schema';\n--\n-- The record keeps its single PRIMARY owner on <table>.owner_id (unchanged). This table adds any\n-- number of CO-owners — peers who also see the record in their lists and reports — without touching\n-- owner_id. One shared table across the four entity types (entity_type + entity_id), so the backend\n-- resolves \"records I co-own\" and \"co-owners of this record\" with one query each.\n\nCREATE TABLE IF NOT EXISTS public.crm_record_owners (\n  id          uuid        PRIMARY KEY DEFAULT gen_random_uuid(),\n  org_id      uuid        NOT NULL,\n  client_id   uuid,\n  entity_type text        NOT NULL,          -- 'lead' | 'account' | 'contact' | 'deal'\n  entity_id   uuid        NOT NULL,\n  user_id     uuid        NOT NULL,          -- a co-owner (never the primary owner_id)\n  created_at  timestamptz NOT NULL DEFAULT now(),\n  created_by  uuid,\n  deleted_at  timestamptz\n);\n\n-- entity_type is one of four values. Added idempotently (ADD CONSTRAINT has no IF NOT EXISTS).\nDO $$ BEGIN\n  IF NOT EXISTS (SELECT 1 FROM pg_constraint\n                 WHERE conname = 'crm_record_owners_entity_type_check' AND conrelid = 'public.crm_record_owners'::regclass) THEN\n    ALTER TABLE public.crm_record_owners\n      ADD CONSTRAINT crm_record_owners_entity_type_check\n      CHECK (entity_type IN ('lead', 'account', 'contact', 'deal'));\n  END IF;\nEND $$;\n\n-- One live co-owner row per (entity, user): re-adding the same person is a no-op, never a duplicate.\nCREATE UNIQUE INDEX IF NOT EXISTS ux_crm_record_owners_entity_user\n  ON public.crm_record_owners (entity_type, entity_id, user_id) WHERE deleted_at IS NULL;\n-- \"records of type T that user U co-owns\" — the read-scope widening.\nCREATE INDEX IF NOT EXISTS idx_crm_record_owners_user\n  ON public.crm_record_owners (org_id, user_id, entity_type) WHERE deleted_at IS NULL;\n-- \"co-owners of this record\".\nCREATE INDEX IF NOT EXISTS idx_crm_record_owners_entity\n  ON public.crm_record_owners (entity_type, entity_id) WHERE deleted_at IS NULL;\n\n-- RLS: the service-role backend (supabaseAdmin) bypasses RLS; enable it so no other role can read,\n-- matching the sibling Spark tables (crm_lead_contacts, crm_activity_assignees).\nDO $$\nBEGIN\n  EXECUTE 'ALTER TABLE public.crm_record_owners ENABLE ROW LEVEL SECURITY';\n  EXECUTE 'GRANT SELECT, INSERT, UPDATE, DELETE ON public.crm_record_owners TO authenticated, service_role';\nEND $$;\n\nNOTIFY pgrst, 'reload schema';\n" },
  { name: "migration_product_make_text.sql", sql: "-- Free-text \"Make\" on a CRM product (Spark & Ray).\n--\n-- The product's make was previously a link to the Makes master list (crm_products.make_id → crm_makes).\n-- It is now a plain typed string on the product, so a rep types the manufacturer directly and there is no\n-- separate Makes settings list to maintain. This adds the text column; the old make_id column is left in place\n-- (existing links keep resolving, and nothing is dropped).\n--\n-- Additive and idempotent.\nALTER TABLE public.crm_products ADD COLUMN IF NOT EXISTS make text;\n\n-- PostgREST caches the schema; tell it to reload so the new column is visible to the API at once.\nNOTIFY pgrst, 'reload schema';\n" },
  { name: "migration_support_tickets.sql", sql: "-- Support tickets (Help & Support in the dashboard, \"Raise an issue\" on KINI WhatsApp, the support inbox).\n-- One queue for every customer, whatever project their data lives in: always stored in the Kinematic project\n-- (services/support/supportTickets.service.ts writes here explicitly). Additive and idempotent. Kinematic project only.\nCREATE SEQUENCE IF NOT EXISTS public.support_ticket_seq START 5001;\n\nCREATE TABLE IF NOT EXISTS public.support_tickets (\n  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  ref                text NOT NULL DEFAULT ('KM-' || nextval('public.support_ticket_seq')::text),\n  status             text NOT NULL DEFAULT 'open'\n                     CHECK (status IN ('open', 'in_progress', 'waiting_on_customer', 'resolved', 'closed')),\n  priority           text NOT NULL DEFAULT 'normal' CHECK (priority IN ('low', 'normal', 'high', 'urgent')),\n  category           text NOT NULL DEFAULT 'other'\n                     CHECK (category IN ('how_to', 'bug', 'data', 'billing', 'feature_request', 'other')),\n  subject            text NOT NULL,\n  description        text NOT NULL,\n  channel            text NOT NULL DEFAULT 'dashboard' CHECK (channel IN ('whatsapp', 'dashboard', 'app')),\n  project_key        text,\n  org_id             uuid,\n  org_name           text,\n  raised_by_user_id  uuid,\n  contact_name       text,\n  contact_phone      text,\n  contact_email      text,\n  resolution_note    text,\n  created_at         timestamptz NOT NULL DEFAULT now(),\n  updated_at         timestamptz NOT NULL DEFAULT now(),\n  resolved_at        timestamptz\n);\nCREATE UNIQUE INDEX IF NOT EXISTS uq_support_tickets_ref ON public.support_tickets (ref);\nCREATE INDEX IF NOT EXISTS idx_support_tickets_status ON public.support_tickets (status, created_at DESC);\nCREATE INDEX IF NOT EXISTS idx_support_tickets_org ON public.support_tickets (project_key, org_id, created_at DESC);\nCREATE INDEX IF NOT EXISTS idx_support_tickets_phone ON public.support_tickets (contact_phone);\n\nCREATE TABLE IF NOT EXISTS public.support_ticket_events (\n  id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  ticket_id    uuid NOT NULL REFERENCES public.support_tickets(id) ON DELETE CASCADE,\n  kind         text NOT NULL CHECK (kind IN ('created', 'status', 'comment')),\n  author_type  text NOT NULL CHECK (author_type IN ('customer', 'team', 'system')),\n  author_name  text,\n  from_status  text,\n  to_status    text,\n  body         text,\n  created_at   timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX IF NOT EXISTS idx_support_ticket_events_ticket ON public.support_ticket_events (ticket_id, created_at);\n\nALTER TABLE public.support_tickets ENABLE ROW LEVEL SECURITY;        -- deny-by-default; service-role bypasses\nALTER TABLE public.support_ticket_events ENABLE ROW LEVEL SECURITY;\nNOTIFY pgrst, 'reload schema';\n" },
  { name: "migration_support_tickets_v2.sql", sql: "-- Support tickets v2 — the ticketing module every tenant gets by default.\n--\n-- What changes:\n--   * `category` becomes the ticket TYPE, with the taxonomy the product needs: how-to, issue, bug,\n--     change request, new module, data correction, billing, access request, training, other.\n--     The two old names that no longer fit are migrated (data → data_correction,\n--     feature_request → new_module); the service still accepts the old names on input.\n--   * `status` gains `triaged`, `release_pending` and `rejected`.\n--   * `platforms` (text[]) records where the customer hit it — web / android / ios / whatsapp / other.\n--   * `area` records which part of the product it is about (generic Kinematic modules, never a\n--     per-client column — a client's own taxonomy belongs in custom fields).\n--   * `first_response_at` stamps the team's first reply, so SLA reporting has something to measure.\n--\n-- Additive and idempotent. Kinematic project only (every ticket lives in SUPPORT_PROJECT).\nBEGIN;\n\n-- ── New columns ───────────────────────────────────────────────────────────────────────────────────\nALTER TABLE public.support_tickets\n  ADD COLUMN IF NOT EXISTS platforms         text[] NOT NULL DEFAULT '{}',\n  ADD COLUMN IF NOT EXISTS area              text,\n  ADD COLUMN IF NOT EXISTS first_response_at timestamptz;\n\n-- ── Category: widen first, then migrate the two renamed values ────────────────────────────────────\nALTER TABLE public.support_tickets DROP CONSTRAINT IF EXISTS support_tickets_category_check;\nUPDATE public.support_tickets SET category = 'data_correction' WHERE category = 'data';\nUPDATE public.support_tickets SET category = 'new_module'      WHERE category = 'feature_request';\nALTER TABLE public.support_tickets\n  ADD CONSTRAINT support_tickets_category_check CHECK (category IN (\n    'how_to', 'issue', 'bug', 'change_request', 'new_module',\n    'data_correction', 'billing', 'access_request', 'training', 'other'\n  ));\n\n-- ── Status: three new ones ────────────────────────────────────────────────────────────────────────\nALTER TABLE public.support_tickets DROP CONSTRAINT IF EXISTS support_tickets_status_check;\nALTER TABLE public.support_tickets\n  ADD CONSTRAINT support_tickets_status_check CHECK (status IN (\n    'open', 'triaged', 'in_progress', 'waiting_on_customer', 'release_pending',\n    'resolved', 'closed', 'rejected'\n  ));\n\n-- ── Platforms: only the values the product offers ─────────────────────────────────────────────────\nALTER TABLE public.support_tickets DROP CONSTRAINT IF EXISTS support_tickets_platforms_check;\nALTER TABLE public.support_tickets\n  ADD CONSTRAINT support_tickets_platforms_check CHECK (\n    platforms <@ ARRAY['web', 'android', 'ios', 'whatsapp', 'other']::text[]\n  );\n\n-- ── Indexes for the new list filters ──────────────────────────────────────────────────────────────\nCREATE INDEX IF NOT EXISTS idx_support_tickets_category  ON public.support_tickets (category, created_at DESC);\nCREATE INDEX IF NOT EXISTS idx_support_tickets_area      ON public.support_tickets (area, created_at DESC);\nCREATE INDEX IF NOT EXISTS idx_support_tickets_platforms ON public.support_tickets USING gin (platforms);\n\nCOMMIT;\nNOTIFY pgrst, 'reload schema';\n" },
  { name: "migration_support_tickets_feedback.sql", sql: "-- Support tickets: customer feedback (CSAT) on a finished ticket.\n--\n-- The customer rates how the ticket was handled once it is resolved, closed or not planned, with an\n-- optional comment. Stored on the row (one rating per ticket, re-submittable), and recorded on the\n-- timeline as a `feedback` event so the team sees it in the thread.\n--\n-- Additive and idempotent. Kinematic project only (every ticket lives in SUPPORT_PROJECT).\nBEGIN;\n\nALTER TABLE public.support_tickets\n  ADD COLUMN IF NOT EXISTS csat_rating  smallint,\n  ADD COLUMN IF NOT EXISTS csat_comment text,\n  ADD COLUMN IF NOT EXISTS csat_at      timestamptz;\n\nALTER TABLE public.support_tickets DROP CONSTRAINT IF EXISTS support_tickets_csat_rating_check;\nALTER TABLE public.support_tickets\n  ADD CONSTRAINT support_tickets_csat_rating_check\n  CHECK (csat_rating IS NULL OR (csat_rating >= 1 AND csat_rating <= 5));\n\n-- The timeline gains a fourth entry kind.\nALTER TABLE public.support_ticket_events DROP CONSTRAINT IF EXISTS support_ticket_events_kind_check;\nALTER TABLE public.support_ticket_events\n  ADD CONSTRAINT support_ticket_events_kind_check\n  CHECK (kind IN ('created', 'status', 'comment', 'feedback'));\n\n-- Only rated tickets matter for a CSAT report, so keep the index partial.\nCREATE INDEX IF NOT EXISTS idx_support_tickets_csat\n  ON public.support_tickets (csat_rating, csat_at DESC) WHERE csat_rating IS NOT NULL;\n\nCOMMIT;\nNOTIFY pgrst, 'reload schema';\n" },
  { name: "migration_support_tickets_attachments.sql", sql: "-- Support tickets: screenshots (and other images) attached when the ticket is raised.\n--\n-- Each entry is { path, bucket, name, size, content_type, uploaded_at }. The files live in the\n-- SUPPORT project's own private bucket, never the customer's, so that both the customer (whose\n-- data may be in any project) and a platform operator (who works in the Kinematic project) can be\n-- served a signed URL for the same object. See services/support/supportAttachments.ts.\n--\n-- Additive and idempotent. Kinematic project only (every ticket lives in SUPPORT_PROJECT).\nBEGIN;\n\nALTER TABLE public.support_tickets\n  ADD COLUMN IF NOT EXISTS attachments jsonb NOT NULL DEFAULT '[]'::jsonb;\n\n-- An array, always: the service reads it with .map(), so an object here would throw at runtime.\nALTER TABLE public.support_tickets DROP CONSTRAINT IF EXISTS support_tickets_attachments_check;\nALTER TABLE public.support_tickets\n  ADD CONSTRAINT support_tickets_attachments_check\n  CHECK (jsonb_typeof(attachments) = 'array');\n\nCOMMIT;\nNOTIFY pgrst, 'reload schema';\n" },
  { name: "migration_crm_form_lead_capture.sql", sql: "-- Per-form \"create a CRM lead on submit\" toggle (Maa Mansha Pharma lead capture).\n-- Additive + idempotent. When true, submitForm maps the submission's answers\n-- (by each question's prefill_key / type) into a crm_lead. Default false, so no\n-- existing form or tenant changes behaviour.\nALTER TABLE public.builder_forms\n  ADD COLUMN IF NOT EXISTS create_lead_on_submit boolean NOT NULL DEFAULT false;\n\nNOTIFY pgrst, 'reload schema';\n" },
];
